-- Class notes synopsis batch 6: California Spikenard through Chamomile

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>California Spikenard</strong> (Aralia californica, Queen of the Forest) is a <strong>warming</strong>, <strong>antimicrobial</strong>, <strong>antiviral</strong>, <strong>antispasmodic</strong>, <strong>expectorant</strong>, <strong>anti-catarrhal</strong>, <strong>anti-inflammatory</strong>, <strong>diaphoretic</strong>, <strong>alterative</strong>, <strong>carminative</strong>, and <strong>nervine</strong> - both a <strong>cough suppressant</strong> and <strong>expectorant</strong>; a very good restorative after extreme <strong>lung damage</strong>. Used for <strong>bronchitis</strong>, <strong>hot/damp cough</strong>, and <strong>respiratory deficiency</strong> (to increase mucus secretion in tissues); the constitutional picture is tense and tight, can't catch breath. For <strong>cold and dry lung</strong>, combine with <a href="?herb=78"><strong>Licorice</strong></a> as warming and moistening agents. Said to connect air and water - "plants that support our lungs connect us with everything." Grounding, balancing, and calming. Root is used for respiratory distress; berries are more adaptogenic. Found in Huckleberry Regional Preserve in Berkeley.$$
WHERE common_name = 'California Spikenard';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Cannabis</strong> is used topically as an <strong>analgesic</strong> for <strong>rheumatoid arthritis</strong>; CBD is recommended for <strong>cancer</strong> support alongside <a href="?herb=203"><strong>Turmeric</strong></a> and <a href="?herb=137"><strong>Passionflower</strong></a>.$$
WHERE common_name = 'Cannabis';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Cardamom</strong> is a <strong>pungent</strong>, <strong>warming</strong> <strong>carminative</strong>, <strong>digestive bitter</strong>, <strong>digestive stimulant</strong>, and <strong>demulcent</strong> (for dry constitution); rich in volatile oils that move energy downward - helpful for both <strong>GI wind</strong>, <strong>gas</strong>, and <strong>bloating</strong>, and for scattered thoughts; a carminative for <strong>hypochlorhydria</strong>. It is <strong>antifungal</strong> and listed as a spice for both Wet and Dry constitutions; indicated as a digestive bitter and carminative for <strong>rheumatoid arthritis</strong>. When nervous system symptoms correlate with bloating, use Cardamom as a bitter in a glycerite; can be infused into honey to sweeten teas. Volatile oils in Cardamom (along with <a href="?herb=124"><strong>Ginger</strong></a> and <a href="?herb=76"><strong>Fennel</strong></a>) are not ideal for standard decoction - cover the pot to retain volatile oils. Featured in a bitter digestive tincture for thyroid/Hashimoto's cases with <a href="?herb=983"><strong>Blue Vervain</strong></a> and <a href="?herb=124"><strong>Ginger</strong></a>; in an ashwagandha milk formula for sleep (<a href="?herb=20"><strong>Ashwagandha</strong></a> powder with <a href="?herb=167"><strong>Cinnamon</strong></a>, Cardamom, and nutmeg at night); and in a tincture with <a href="?herb=16"><strong>Rhodiola</strong></a> and <a href="?herb=76"><strong>Fennel</strong></a> at five drops three times a day.$$
WHERE common_name = 'Cardamom';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Cascara Sagrada</strong> is a potent <strong>laxative</strong> for <strong>constipation</strong> - used as a last resort alongside <a href="?herb=216"><strong>Senna</strong></a>.$$
WHERE common_name = 'Cascara Sagrada';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Cat's Claw</strong> is an <strong>immune amphoteric</strong> (deep nourisher), cooling, <strong>anti-inflammatory</strong>, and <strong>tissue-soothing</strong> herb, notably powerful for <strong>GI</strong> conditions and used for support during <strong>chemotherapy</strong>.$$
WHERE common_name = 'Cat''s Claw';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Catnip</strong> is a <strong>cooling</strong>, <strong>drying</strong>, <strong>relaxing</strong>, <strong>carminative</strong>, <strong>antispasmodic</strong>, <strong>diaphoretic</strong>, <strong>sedative</strong>, and <strong>digestive nervine</strong> - nurturing, nutritive, and calming; listed in the African American Materia Medica among the 108 documented species. As a carminative, its volatile oils move things after meals and are helpful for both <strong>GI wind</strong> and scattered thoughts - always cover infusions to trap volatile oils; used for <strong>hypochlorhydria</strong> and as a cooling GI tonic and nervine for <strong>hyperchlorhydria</strong>; an <strong>antispasmodic</strong> for <strong>upper GI excess</strong> with pain and for the spasmodic state in <strong>diarrhea</strong> alongside <a href="?herb=76"><strong>Fennel</strong></a>, <a href="?herb=84"><strong>Chamomile</strong></a>, <a href="?herb=167"><strong>Cinnamon</strong></a>, <a href="?herb=55"><strong>Peppermint</strong></a>, and <a href="?herb=124"><strong>Ginger</strong></a>. Used for <strong>digestive ailments</strong> - <strong>diarrhea</strong> and <strong>colic</strong> - in traditional Black American herbalism; a go-to for <strong>GI-based depression</strong> (gut-brain axis). As a <strong>diaphoretic</strong> that promotes sweating without heating up the system (unlike ginger) - excellent for <strong>fever</strong> and <strong>influenza</strong>, with infant fever baths as strong tea. Especially good for children: for <strong>worry</strong>, <strong>fear</strong>, <strong>anxiety</strong>, and <strong>embarrassment</strong>; for restless, nervous, colicky infants and kids; historical formula to calm a fussy colic baby pairs Catnip with <a href="?herb=56"><strong>Sage</strong></a>; listed alongside Magnesium and <a href="?herb=128"><strong>California Poppy</strong></a> for children with <strong>nervous system issues</strong>. As a nervine: specifically indicated for <strong>headache</strong>; moistening for <strong>anxiety</strong>; used for <strong>stress-induced GI symptoms</strong> with <a href="?herb=84"><strong>Chamomile</strong></a>; listed for <strong>heart bypass</strong> support (calming so the brain signals more efficiently); and listed as a nervine and <strong>anti-inflammatory</strong> for <strong>cancer</strong> support. As a <strong>sedative</strong>: in Lisa's sleep tincture with <a href="?herb=2624"><strong>Pedicularis</strong></a> and <a href="?herb=2461"><strong>Jamaican Dogwood</strong></a>; added to Feri's stress glycerite with <a href="?herb=142"><strong>Skullcap</strong></a> for nighttime sleep support; in a stress formula with <a href="?herb=134"><strong>Lemon Balm</strong></a> and <a href="?herb=84"><strong>Chamomile</strong></a>; in a gut healing tea with <a href="?herb=84"><strong>Chamomile</strong></a>, <a href="?herb=124"><strong>Ginger</strong></a>, and <a href="?herb=76"><strong>Fennel</strong></a> for childhood diarrhea; as a sedative in a tincture formula for <strong>fibroids</strong> and <strong>vaginitis</strong>. Tincture combined with <a href="?herb=128"><strong>California Poppy</strong></a> as antidote to over-caffeination. If nauseous from bitters, use Catnip as a carminative alternative alongside <a href="?herb=124"><strong>Ginger</strong></a> or <a href="?herb=134"><strong>Lemon Balm</strong></a>. Safe for animals and a natural insect repellent (part of the mint family); also used for animals who internalize and hold stress (liver gets congested). Listed in the volatile-oils activity group alongside <a href="?herb=115"><strong>Mugwort</strong></a>, <a href="?herb=134"><strong>Lemon Balm</strong></a>, and <a href="?herb=84"><strong>Chamomile</strong></a>.$$
WHERE common_name = 'Catnip';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Cayenne</strong> is a <strong>warming</strong>, <strong>styptic</strong>, circulatory-stimulating herb and Thompson's Standard Protocol's "stoke the fire" herb; it is an <strong>anti-platelet</strong> (not a blood thinner per se, but anti-platelet) that relaxes <strong>capillaries</strong>, allowing medicinal ingredients to reach the tissues. As a <strong>styptic</strong> (stops bleeding), used for profuse bleeding from cuts alongside <a href="?herb=44"><strong>Yarrow</strong></a>, <a href="?herb=217"><strong>Coffee</strong></a>, and <a href="?herb=71"><strong>Shepherd's Purse</strong></a>. A circulatory stimulant (blood and lymph) for <strong>cold constitution</strong> alongside <a href="?herb=1009"><strong>Dong Quai</strong></a>, <a href="?herb=123"><strong>Prickly Ash</strong></a>, <a href="?herb=35"><strong>Poke Root</strong></a> (lymph), <a href="?herb=70"><strong>Calendula</strong></a> (lymph), and <a href="?herb=1248"><strong>Ocotillo</strong></a> (lymph). For <strong>upper GI deficiency</strong>, used as a functional stimulant alongside <a href="?herb=65"><strong>Angelica</strong></a>, <a href="?herb=123"><strong>Prickly Ash</strong></a>, and <a href="?herb=14"><strong>Ginseng</strong></a>. A spirit remedy for <strong>transformation</strong> in the context of depression.$$
WHERE common_name = 'Cayenne';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Celery Seed</strong> is <strong>moistening</strong> - listed as a moistening spice for Dry constitution, indicated for <strong>dry gut</strong>; noted in Ayurveda as hormone-supporting ("any tiny seeds help with hormone production"). In the <strong>eczema</strong> materia medica, it helps the body liquify and eliminate waste through the <strong>bowel</strong>.$$
WHERE common_name = 'Celery Seed';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Chaga</strong> reduces <strong>inflammation</strong> in <strong>pancreatitis</strong>; it is not medicinally active until heated.$$
WHERE common_name = 'Chaga';

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Chamomile</strong> is a <strong>cooling</strong>, <strong>bitter</strong>, <strong>drying</strong>, <strong>relaxing</strong> <strong>nervine</strong> and <strong>carminative</strong> called "the superstar of the GI system" and "for babies of all ages" (Matthew Wood) - specific for fussiness, irritability, and over-reactivity. As the least bitter of the bitters, it stimulates the digestive system and is <strong>anti-inflammatory</strong> to the GI; rich in volatile oils, good taken after a meal; a GI <strong>demulcent</strong> - prefer glycerites, honeys, or vinegars over alcohol when working with the digestive system. Preparation matters: hot infusion is more sedative; cold infusion is less sleepy (fresh quick cold infusion zapped with an immersion blender is playful and joyful - harvest when petals are open in the sun). High dose (1 tsp) at trigger time provides almost immediate relief of <strong>enteric nervous system</strong> triggers; therapeutic dosage 1-2 droppers; for spirit contact, only a few drops. <strong>Antispasmodic</strong> for <strong>cramping</strong> and <strong>diarrhea</strong> alongside <a href="?herb=76"><strong>Fennel</strong></a>, <a href="?herb=136"><strong>Catnip</strong></a>, <a href="?herb=167"><strong>Cinnamon</strong></a>, <a href="?herb=55"><strong>Peppermint</strong></a>, and <a href="?herb=124"><strong>Ginger</strong></a>; Chamomile, <a href="?herb=82"><strong>Lavender</strong></a>, and <a href="?herb=44"><strong>Yarrow</strong></a> are the three general GI superstars. Used for <strong>Hot Damp Diarrhea</strong>; <strong>antiemetic</strong> for <strong>nausea</strong>; paired with <a href="?herb=55"><strong>Peppermint</strong></a> for <strong>nausea and vomiting in pregnancy</strong>. First herb for <strong>stomach cramps in pregnancy</strong> - nip in the bud to prevent triggering uterine cramps; calming and <strong>anti-inflammatory</strong> during pregnancy; binds to <strong>GABA receptors</strong> for <strong>anxiety</strong>; for <strong>insomnia in pregnancy</strong>; used for <strong>heartburn</strong> and <strong>indigestion</strong> insomnia. Cooling GI tonic and nervine for <strong>hyperchlorhydria</strong>; cold infusion for <strong>hypochlorhydria</strong>; listed as a top herb for <strong>urinary</strong> system support; supports the <strong>rest and digest response</strong>; used for <strong>GI-based depression</strong> (gut-brain axis). <strong>Nervine</strong> for <strong>ADHD</strong>, <strong>anxiety</strong>, and <strong>fear</strong> - also for children's fear, worry, anxiety, and embarrassment; combined with <a href="?herb=136"><strong>Catnip</strong></a> for stress-induced GI symptoms; hydration support during <strong>fevers</strong> alongside <a href="?herb=45"><strong>Marshmallow</strong></a>. In the nervine list alongside <a href="?herb=134"><strong>Lemon Balm</strong></a>, <a href="?herb=136"><strong>Catnip</strong></a>, <a href="?herb=137"><strong>Passionflower</strong></a>, <a href="?herb=142"><strong>Skullcap</strong></a>, and <a href="?herb=983"><strong>Blue Vervain</strong></a>; adaptogens for the same context: <a href="?herb=2629"><strong>Andrographis</strong></a>, <a href="?herb=13"><strong>Tulsi</strong></a> (carminative), and <a href="?herb=852"><strong>Shatavari</strong></a> (moistening). For sleep: in "Sleepy Horsey" tea with <a href="?herb=13"><strong>Tulsi</strong></a>, <a href="?herb=82"><strong>Lavender</strong></a>, and <a href="?herb=151"><strong>Horsetail</strong></a>; in a post-menopausal case glycerite with <a href="?herb=90"><strong>Linden</strong></a> and <a href="?herb=76"><strong>Fennel</strong></a> for poor sleep, restlessness, and gas/bloating; in a stress formula with <a href="?herb=136"><strong>Catnip</strong></a> and <a href="?herb=134"><strong>Lemon Balm</strong></a>. A washcloth soaked in hot-to-cold infusion can be applied over the face; also considered for <strong>dry eyes</strong>. Mentioned with <a href="?herb=420"><strong>Basil</strong></a> to sweeten dreams if nightmares occur; add to <a href="?herb=115"><strong>Mugwort</strong></a> cold infusion to balance. Listed in the volatile-oils activity group alongside <a href="?herb=115"><strong>Mugwort</strong></a>, <a href="?herb=134"><strong>Lemon Balm</strong></a>, and <a href="?herb=136"><strong>Catnip</strong></a>. For pets: good for dogs and cats - use dry for digestion, fresh for behavior; cools and relaxes; used for horses with <strong>colic</strong> pain; for soothing skin and mucosa (anal gland abscesses); GI use for vomiting with mucus. Historical formulas: for chills, aches, and fever with <a href="?herb=313"><strong>Sassafras</strong></a> and Peach Leaf; for immune support with <a href="?herb=56"><strong>Sage</strong></a> and <a href="?herb=89"><strong>Comfrey</strong></a>; in the traditional African American glycerine syrup alongside <a href="?herb=89"><strong>Comfrey</strong></a>, <a href="?herb=56"><strong>Sage</strong></a>, and <a href="?herb=134"><strong>Lemon Balm</strong></a> or mint. In wound wash vulnerary blend with <a href="?herb=44"><strong>Yarrow</strong></a>, <a href="?herb=85"><strong>Plantain</strong></a>, <a href="?herb=70"><strong>Calendula</strong></a>, <a href="?herb=82"><strong>Lavender</strong></a>, <a href="?herb=2437"><strong>Self Heal</strong></a>, and <a href="?herb=88"><strong>Chickweed</strong></a>.$$
WHERE common_name = 'Chamomile';
